) VALUES (
    'marco-schwarz-profile',
    '{"en": "Marco Schwarz: The Complete Alpine Skier", "de": "Marco Schwarz: Der komplette Skirennläufer", "fr": "Marco Schwarz : Le skieur alpin complet", "it": "Marco Schwarz: Lo sciatore alpino completo", "es": "Marco Schwarz: El esquiador alpino completo", "pt": "Marco Schwarz: O esquiador alpino completo", "nl": "Marco Schwarz: De complete alpine skiër", "ar": "ماركو شوارتز: المتزلج الألبي الكامل", "ja": "マルコ・シュヴァルツ：完璧なアルペンスキーヤー", "zh": "Marco Schwarz: Wanmei de Gaoshan Huaxue Xuanshou", "ko": "마르코 슈바르츠: 완벽한 알파인 스키어"}'::jsonb,
    '{"en": "Schwarz excels in every alpine discipline, from slalom to super-G. The Austrian world champion represents the rare breed of true all-rounders in modern skiing.", "de": "Schwarz brilliert in jeder alpinen Disziplin, vom Slalom bis zum Super-G.", "fr": "Schwarz excelle dans toutes les disciplines alpines, du slalom au super-G.", "it": "Schwarz eccelle in ogni disciplina alpina, dallo slalom al super-G.", "es": "Schwarz destaca en todas las disciplinas alpinas, del eslalom al super-G.", "pt": "Schwarz se destaca em todas as disciplinas alpinas, do slalom ao super-G.", "nl": "Schwarz blinkt uit in elke alpine discipline, van slalom tot super-G.", "ar": "يتفوق شوارتز في كل تخصصات التزلج الألبي", "ja": "シュヴァルツはスラロームからスーパーGまで、あらゆるアルペン種目で優れています。", "zh": "Schwarz zai suoyou gaoshan huaxue xiangmu zhong dou biaoxian chuse.", "ko": "슈바르츠는 슬라럼부터 슈퍼G까지 모든 알파인 종목에서 뛰어납니다."}'::jsonb,
    '{"en": "<p>Marco Schwarz is one of the most versatile athletes in World Cup <a href=\"/alpine-skiing-guide/\">alpine skiing</a>. The Austrian can compete at the highest level in slalom, giant slalom, super-G, and combined - a rare talent in an era of specialization.</p><h2>World Champion</h2><p>Schwarz has proven his all-around abilities at the World Championships. His world title in combined showcased his unique ability to excel in both technical and speed disciplines within the same competition.</p><p>This versatility makes him a threat in any race format and a valuable asset to the Austrian team.</p><h2>Technical Excellence</h2><p>In slalom, Schwarz battles against specialists like <a href=\"/manuel-feller-profile/\">Manuel Feller</a>, <a href=\"/clement-noel-profile/\">Clement Noel</a>, and <a href=\"/henrik-kristoffersen-profile/\">Henrik Kristoffersen</a>. His ability to compete with pure slalom specialists while also excelling in speed events demonstrates his exceptional talent.</p><h2>Speed Capabilities</h2><p>What sets Schwarz apart is his super-G performance. While many technical specialists struggle in speed events, Schwarz has posted world-class results against dedicated speed racers.</p><h2>Combined Master</h2><p>The combined event - featuring both downhill and slalom - plays perfectly to Schwarz''s strengths. He can stay competitive in the speed portion and then attack in the technical run.</p><h2>Complete Package</h2><p>Athletes like Schwarz remind fans why alpine skiing''s all-around competitions remain so compelling. His ability to adapt to any discipline makes every race an opportunity for success.</p>", "de": "<p>Marco Schwarz ist einer der vielseitigsten Athleten im Weltcup-<a href=\"/alpine-skiing-guide/\">Ski Alpin</a>. Der Österreicher kann auf höchstem Niveau in Slalom, Riesenslalom, Super-G und Kombination antreten.</p><h2>Weltmeister</h2><p>Schwarz hat seine Allround-Fähigkeiten bei den Weltmeisterschaften bewiesen. Sein WM-Titel in der Kombination zeigte seine einzigartige Fähigkeit.</p><h2>Technische Exzellenz</h2><p>Im Slalom kämpft Schwarz gegen Spezialisten wie <a href=\"/manuel-feller-profile/\">Manuel Feller</a> und <a href=\"/clement-noel-profile/\">Clement Noel</a>.</p><h2>Speed-Fähigkeiten</h2><p>Was Schwarz auszeichnet, ist seine Super-G-Leistung.</p><h2>Kombinations-Meister</h2><p>Die Kombination spielt perfekt zu Schwarz'' Stärken.</p>", "fr": "<p>Marco Schwarz est l''un des athlètes les plus polyvalents de la Coupe du monde de <a href=\"/alpine-skiing-guide/\">ski alpin</a>. L''Autrichien peut concourir au plus haut niveau en slalom, géant, super-G et combiné.</p><h2>Champion du monde</h2><p>Schwarz a prouvé ses capacités polyvalentes aux Championnats du monde.</p><h2>Excellence technique</h2><p>En slalom, Schwarz affronte des spécialistes comme <a href=\"/manuel-feller-profile/\">Manuel Feller</a> et <a href=\"/clement-noel-profile/\">Clement Noel</a>.</p><h2>Capacités en vitesse</h2><p>Ce qui distingue Schwarz, c''est sa performance en super-G.</p>", "it": "<p>Marco Schwarz è uno degli atleti più versatili nella Coppa del Mondo di <a href=\"/alpine-skiing-guide/\">sci alpino</a>. L''austriaco può competere al massimo livello in slalom, gigante, super-G e combinata.</p><h2>Campione del mondo</h2><p>Schwarz ha dimostrato le sue capacità complete ai Mondiali.</p><h2>Eccellenza tecnica</h2><p>Nello slalom, Schwarz affronta specialisti come <a href=\"/manuel-feller-profile/\">Manuel Feller</a>.</p><h2>Capacità nella velocità</h2><p>Ciò che distingue Schwarz è la sua prestazione in super-G.</p>", "es": "<p>Marco Schwarz es uno de los atletas más versátiles en la Copa del Mundo de <a href=\"/alpine-skiing-guide/\">esquí alpino</a>. El austriaco puede competir al más alto nivel en eslalom, gigante, super-G y combinada.</p><h2>Campeón mundial</h2><p>Schwarz ha demostrado sus habilidades completas en los Campeonatos Mundiales.</p><h2>Excelencia técnica</h2><p>En eslalom, Schwarz compite contra especialistas.</p>", "pt": "<p>Marco Schwarz é um dos atletas mais versáteis da Copa do Mundo de <a href=\"/alpine-skiing-guide/\">esqui alpino</a>. O austríaco pode competir no mais alto nível em slalom, gigante, super-G e combinado.</p><h2>Campeão mundial</h2><p>Schwarz provou suas habilidades completas nos Campeonatos Mundiais.</p>", "nl": "<p>Marco Schwarz is een van de meest veelzijdige atleten in de Wereldbeker <a href=\"/alpine-skiing-guide/\">alpine skiën</a>. De Oostenrijker kan op het hoogste niveau concurreren in slalom, reuzenslalom, super-G en combinatie.</p><h2>Wereldkampioen</h2><p>Schwarz heeft zijn allround vaardigheden bewezen op de WK.</p>", "ar": "<p>ماركو شوارتز هو أحد أكثر الرياضيين تنوعاً في كأس العالم <a href=\"/alpine-skiing-guide/\">للتزلج الألبي</a>. يمكن للنمساوي المنافسة على أعلى مستوى في جميع التخصصات.</p><h2>بطل العالم</h2><p>أثبت شوارتز قدراته الشاملة في بطولة العالم.</p>", "ja": "<p>マルコ・シュヴァルツは、ワールドカップ<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>で最も多才な選手の一人です。オーストリア人は、スラローム、ジャイアントスラローム、スーパーG、コンバインドで最高レベルで競争できます。</p><h2>世界チャンピオン</h2><p>シュヴァルツは世界選手権でオールラウンドな能力を証明しました。</p>", "zh": "<p>Marco Schwarz shi Shijie Bei <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> zhong zui duocai de yundongyuan zhiyi. Zhe wei Aodili ren keyi zai huixue, dashanzhuan, chaojidashanzhuan he quanneng xiangmu zhong zuigao shuiping jingzheng.</p><h2>Shijie guanjun</h2><p>Schwarz zai Shijie Jinbiaosai shang zhengming le tade quanmian nengli.</p>", "ko": "<p>마르코 슈바르츠는 월드컵 <a href=\"/alpine-skiing-guide/\">알파인 스키</a>에서 가장 다재다능한 선수 중 하나입니다. 오스트리아인은 슬라럼, 대회전, 슈퍼G, 복합에서 최고 수준으로 경쟁할 수 있습니다.</p><h2>세계 챔피언</h2><p>슈바르츠는 세계 선수권 대회에서 올라운드 능력을 증명했습니다.</p>"}'::jsonb,
    'athlete-profile',
    'AS',
    '{"en": "Marco Schwarz profile - Austrian alpine skiing world champion and versatile all-rounder competing at the highest level in slalom, giant slalom, super-G, and combined.", "de": "Marco Schwarz Profil - Österreichischer Ski-Alpin-Weltmeister und vielseitiger Allrounder.", "fr": "Profil de Marco Schwarz - Champion du monde autrichien de ski alpin et polyvalent.", "it": "Profilo di Marco Schwarz - Campione del mondo austriaco di sci alpino e versatile.", "es": "Perfil de Marco Schwarz - Campeón mundial austriaco de esquí alpino y versátil.", "pt": "Perfil de Marco Schwarz - Campeão mundial austríaco de esqui alpino e versátil.", "nl": "Marco Schwarz profiel - Oostenrijkse wereldkampioen alpine skiën en veelzijdig.", "ar": "ملف ماركو شوارتز - بطل العالم النمساوي في التزلج الألبي", "ja": "マルコ・シュヴァルツのプロフィール - オーストリアのアルペンスキー世界チャンピオン", "zh": "Marco Schwarz jianjie - Aodili gaoshan huaxue shijie guanjun", "ko": "마르코 슈바르츠 프로필 - 오스트리아 알파인 스키 세계 챔피언"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
